<script setup lang="ts">
import { ref } from 'vue'
import { onShow,onPullDownRefresh } from '@dcloudio/uni-app'
import { request,statuses,date,priorities } from '../../api'
import { useSession } from '../../stores/session'
import { backToPreviousTab,noteTabShown } from '../../tabNavigation'
const session=useSession(),rows=ref<any[]>([]),page=ref(1),total=ref(0),status=ref(''),busy=ref(false),error=ref(false)
async function load(reset=true){if(!session.requireLogin())return;if(reset)page.value=1;busy.value=true;error.value=false;try{const result=await request('/repair/orders','GET',{page:page.value,size:15,status:status.value});rows.value=reset?result.records:[...rows.value,...result.records];total.value=result.total}catch{error.value=true}finally{busy.value=false;uni.stopPullDownRefresh()}}
onShow(()=>{noteTabShown('/pages/orders/index');load()});onPullDownRefresh(()=>load())
function filter(value:string){status.value=value;load()}
async function more(){page.value++;await load(false)}
</script>
<template><view class="page"><view class="back-link" @click="backToPreviousTab('/pages/orders/index')">‹ 返回上一步</view><view class="eyebrow">服务进度 · 全程可见</view><view class="page-title">{{session.activeRole==='WORKER'?'维修任务':'我的工单'}}</view><view class="tab-row"><text :class="{active:!status}" @click="filter('')">全部</text><template v-if="session.activeRole==='WORKER'"><text :class="{active:status==='ASSIGNED'}" @click="filter('ASSIGNED')">待接单</text><text :class="{active:status==='ACCEPTED'}" @click="filter('ACCEPTED')">待上门</text><text :class="{active:status==='IN_PROGRESS'}" @click="filter('IN_PROGRESS')">维修中</text></template><template v-else><text :class="{active:status==='SUBMITTED'}" @click="filter('SUBMITTED')">待审核</text><text :class="{active:status==='PENDING_CONFIRM'}" @click="filter('PENDING_CONFIRM')">待验收</text><text :class="{active:status==='CLOSED'}" @click="filter('CLOSED')">已完成</text></template></view><view v-if="error" class="error" @click="load()">加载失败，点击重试</view><view v-if="!rows.length&&!busy&&!error" class="empty">当前没有{{status?statuses[status]:''}}工单</view><view v-for="order in rows" :key="order.id" class="card" @click="uni.navigateTo({url:`/pages/detail/index?id=${order.id}`})"><view class="row"><text class="small">{{order.orderNo}}</text><text class="pill">{{statuses[order.status]}}</text></view><view class="order-title">{{order.title}}</view><view class="muted">{{order.communityName}} · {{order.buildingNo}}栋 {{order.roomNo}}室</view><view class="divider"></view><view class="row"><text class="small">{{priorities[order.priority]}} · {{order.categoryName}}</text><text class="small">{{date(order.createdAt)}}</text></view></view><button v-if="rows.length<total" class="secondary" :loading="busy" @click="more">加载更多</button><view v-if="busy" class="empty">正在加载…</view></view></template>
